package dev.thedocruby.resounding.debug.math;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Closest-distance geometry for debug picking, with no Minecraft on the classpath.
 */
class Segment3Test {

    private static final double EPS = 1e-9;

    @Test
    void parallelSegmentsReportSeparationDistance() {
        Segment3 lower = new Segment3(0, 0, 0, 1, 0, 0);
        Segment3 upper = new Segment3(0, 2, 0, 1, 2, 0);

        assertEquals(2.0, lower.closestDistanceTo(upper), EPS);
        assertEquals(2.0, upper.closestDistanceTo(lower), EPS);
    }

    @Test
    void skewSegmentsReportShortestDistanceBetweenInfiniteLinesClampedToSegments() {
        Segment3 alongX = new Segment3(0, 0, 0, 1, 0, 0);
        Segment3 alongZ = new Segment3(0, 1, 1, 0, 1, 2);

        assertEquals(Math.sqrt(2.0), alongX.closestDistanceTo(alongZ), EPS);
    }

    @Test
    void overlappingCollinearSegmentsAreCoincident() {
        Segment3 first = new Segment3(0, 0, 0, 2, 0, 0);
        Segment3 second = new Segment3(1, 0, 0, 3, 0, 0);

        assertEquals(0.0, first.closestDistanceTo(second), EPS);
        assertEquals(0.0, second.closestDistanceTo(first), EPS);
    }

    @Test
    void degeneratePointSegmentUsesPointToSegmentDistance() {
        Segment3 point = new Segment3(0.5, 1.0, 0.0, 0.5, 1.0, 0.0);
        Segment3 segment = new Segment3(0, 0, 0, 1, 0, 0);

        assertEquals(1.0, point.closestDistanceTo(segment), EPS);
        assertEquals(1.0, segment.closestDistanceTo(point), EPS);
        assertEquals(1.0, point.closestDistanceToPoint(0.5, 0.0, 0.0), EPS);
    }
}

package dev.thedocruby.resounding.debug.math;

import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Drop-oldest bounded queue semantics, with no Minecraft on the classpath.
 */
class RingBufferTest {

    @Test
    void overflowDropsOldestElementFirst() {
        RingBuffer<String> buffer = new RingBuffer<>(3);
        buffer.offer("a");
        buffer.offer("b");
        buffer.offer("c");
        buffer.offer("d");

        assertEquals(3, buffer.size());
        assertEquals(List.of("b", "c", "d"), buffer.asList());
    }

    @Test
    void capacityZeroNeverStoresAnything() {
        RingBuffer<Integer> buffer = new RingBuffer<>(0);

        buffer.offer(1);
        buffer.offer(2);

        assertEquals(0, buffer.capacity());
        assertEquals(0, buffer.size());
        assertTrue(buffer.asList().isEmpty());
    }

    @Test
    void capacityOneKeepsOnlyTheLatestElement() {
        RingBuffer<Integer> buffer = new RingBuffer<>(1);

        buffer.offer(10);
        buffer.offer(20);

        assertEquals(1, buffer.capacity());
        assertEquals(1, buffer.size());
        assertEquals(List.of(20), buffer.asList());
    }

    @Test
    void iterationOrderMatchesInsertionOrder() {
        RingBuffer<String> buffer = new RingBuffer<>(4);
        buffer.offer("first");
        buffer.offer("second");
        buffer.offer("third");

        assertEquals(List.of("first", "second", "third"), buffer.asList());
    }
}

package dev.thedocruby.resounding.debug.math;

import org.junit.jupiter.api.Test;

import java.util.HashSet;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Octree depth-to-color table, with no Minecraft on the classpath.
 */
class DepthColorTest {

    // Locked-in palette: five distinct ARGB colors, one per valid node size.
    private static final int COLOR_16 = 0xFFFF0000;
    private static final int COLOR_8 = 0xFF00FF00;
    private static final int COLOR_4 = 0xFF0000FF;
    private static final int COLOR_2 = 0xFFFFFF00;
    private static final int COLOR_1 = 0xFFFF00FF;

    @Test
    void validSizesMapToDistinctFixedColors() {
        assertAll(
                () -> assertEquals(COLOR_16, DepthColor.colorForSize(16)),
                () -> assertEquals(COLOR_8, DepthColor.colorForSize(8)),
                () -> assertEquals(COLOR_4, DepthColor.colorForSize(4)),
                () -> assertEquals(COLOR_2, DepthColor.colorForSize(2)),
                () -> assertEquals(COLOR_1, DepthColor.colorForSize(1)));

        Set<Integer> colors = new HashSet<>();
        colors.add(DepthColor.colorForSize(16));
        colors.add(DepthColor.colorForSize(8));
        colors.add(DepthColor.colorForSize(4));
        colors.add(DepthColor.colorForSize(2));
        colors.add(DepthColor.colorForSize(1));
        assertEquals(5, colors.size(), "each valid size must produce a unique color");
    }

    @Test
    void unexpectedSizeThrowsIllegalArgumentException() {
        IllegalArgumentException thrown = assertThrows(
                IllegalArgumentException.class,
                () -> DepthColor.colorForSize(3));
        assertTrue(thrown.getMessage().contains("3"));
    }
}

package dev.thedocruby.resounding.debug;

import dev.thedocruby.resounding.raycast.Branch;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.Box;
import org.junit.jupiter.api.Test;

import java.util.Comparator;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Octree walk that emits one box per node; needs BlockPos/Box but not a running client.
 */
class OctreeOverlayTest {

    private static final double EPS = 1e-9;

    @Test
    void collectOctantsEmitsOneBoxPerNodeForHandBuiltTree() {
        BlockPos rootOrigin = new BlockPos(16, 32, 48);
        Branch root = new Branch(rootOrigin, 8);
        int half = root.size >> 1;

        root.put(rootOrigin.asLong(), new Branch(rootOrigin, half));
        root.put(rootOrigin.add(half, 0, 0).asLong(), new Branch(rootOrigin.add(half, 0, 0), half));
        root.put(rootOrigin.add(0, half, 0).asLong(), new Branch(rootOrigin.add(0, half, 0), half));

        List<Box> boxes = OctreeOverlay.collectOctants(root);

        assertEquals(4, boxes.size(), "root plus three subdivided children");

        boxes.sort(Comparator
                .comparingDouble(Box::minX)
                .thenComparingDouble(Box::minY)
                .thenComparingDouble(Box::minZ));

        assertBox(boxes.get(0), rootOrigin.getX(), rootOrigin.getY(), rootOrigin.getZ(), half);
        assertBox(boxes.get(1), rootOrigin.getX(), rootOrigin.getY() + half, rootOrigin.getZ(), half);
        assertBox(boxes.get(2), rootOrigin.getX() + half, rootOrigin.getY(), rootOrigin.getZ(), half);
        assertBox(boxes.get(3), rootOrigin.getX(), rootOrigin.getY(), rootOrigin.getZ(), root.size);
    }

    private static void assertBox(Box box, int originX, int originY, int originZ, int size) {
        assertEquals(originX, box.minX, EPS);
        assertEquals(originY, box.minY, EPS);
        assertEquals(originZ, box.minZ, EPS);
        assertEquals(originX + size, box.maxX, EPS);
        assertEquals(originY + size, box.maxY, EPS);
        assertEquals(originZ + size, box.maxZ, EPS);
    }
}

package dev.thedocruby.resounding.debug;

import dev.thedocruby.resounding.raycast.Branch;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.Box;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Octree walk that emits one box per node; needs BlockPos/Box but not a running client.
 */
class OctreeOverlayTest {

    private static final double EPS = 1e-9;

    @Test
    void collectOctantsEmitsOneBoxPerNodeForHandBuiltTree() {
        BlockPos rootOrigin = new BlockPos(16, 32, 48);
        Branch root = new Branch(rootOrigin, 8);
        int half = root.size >> 1;

        root.put(rootOrigin.asLong(), new Branch(rootOrigin, half));
        root.put(rootOrigin.add(half, 0, 0).asLong(), new Branch(rootOrigin.add(half, 0, 0), half));
        root.put(rootOrigin.add(0, half, 0).asLong(), new Branch(rootOrigin.add(0, half, 0), half));

        List<Box> boxes = OctreeOverlay.collectOctants(root);

        assertEquals(4, boxes.size(), "root plus three subdivided children");
        assertBoxPresent(boxes, rootOrigin.getX(), rootOrigin.getY(), rootOrigin.getZ(), root.size);
        assertBoxPresent(boxes, rootOrigin.getX(), rootOrigin.getY(), rootOrigin.getZ(), half);
        assertBoxPresent(boxes, rootOrigin.getX() + half, rootOrigin.getY(), rootOrigin.getZ(), half);
        assertBoxPresent(boxes, rootOrigin.getX(), rootOrigin.getY() + half, rootOrigin.getZ(), half);
    }

    private static void assertBoxPresent(List<Box> boxes, int originX, int originY, int originZ, int size) {
        boolean found = boxes.stream().anyMatch(box ->
                Math.abs(box.minX - originX) < EPS
                        && Math.abs(box.minY - originY) < EPS
                        && Math.abs(box.minZ - originZ) < EPS
                        && Math.abs(box.maxX - (originX + size)) < EPS
                        && Math.abs(box.maxY - (originY + size)) < EPS
                        && Math.abs(box.maxZ - (originZ + size)) < EPS);
        assertTrue(found, () -> "expected box at (" + originX + "," + originY + "," + originZ + ") size " + size);
    }
}
